{
  "steps": [
    {
      "action": "Ensure the notice informs the Data Principal of the personal data being collected and the purpose for which it is being collected.",
      "provision_id": "dpdp_act_2023_sec_40"
    },
    {
      "action": "Ensure the notice informs the Data Principal of the intended recipients of the information.",
      "provision_id": "spdi_rules_2011_sec_5"
    },
    {
      "action": "Ensure the notice provides the name and address of the agency collecting the information and the agency that will retain the information.",
      "provision_id": "spdi_rules_2011_sec_5"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify if the incident qualifies as a 'personal data breach' under the Digital Personal Data Protection Act, 2023.",
      "provision_id": "dpdp_act_2023_sec_2"
    },
    {
      "action": "Note that the provided provisions do not specify a mandatory reporting timeline for personal data breaches to the Data Protection Board or affected users under the Digital Personal Data Protection Act, 2023.",
      "provision_id": "dpdp_act_2023_sec_1"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify the definition of verifiable consent as specified in the applicable rules.",
      "provision_id": "dpdp_rules_2025_sec_2"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify the applicable Act for the establishment and submit an application for registration to the registering officer within sixty days of the Act becoming applicable.",
      "provision_id": "bocw_1996_sec_7"
    },
    {
      "action": "Ensure the application includes the prescribed form, required particulars, and the necessary fees.",
      "provision_id": "bocw_1996_sec_7"
    },
    {
      "action": "Receive the certificate of registration issued by the registering officer upon successful processing of the application.",
      "provision_id": "bocw_1996_sec_7"
    },
    {
      "action": "Intimate the registering officer within thirty days regarding any changes in ownership, management, or other prescribed particulars after the initial registration.",
      "provision_id": "bocw_1996_sec_7"
    }
  ]
}

{
  "steps": [
    {
      "action": "Implement a comprehensive documented information security programme and information security policies that contain managerial, technical, operational, and physical security control measures commensurate with the information assets and nature of business.",
      "provision_id": "spdi_rules_2011_sec_8"
    },
    {
      "action": "Ensure security practices and procedures are designed to protect sensitive personal data or information from unauthorised access, damage, use, modification, disclosure, or impairment.",
      "provision_id": "information_technology_act_2000_sec_43A"
    },
    {
      "action": "Demonstrate, when called upon by a mandated agency, that implemented security control measures align with the documented information security programme and policies.",
      "provision_id": "spdi_rules_2011_sec_8"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the recipient body corporate or person ensures the same level of data protection as adhered to by your organization.",
      "provision_id": "spdi_rules_2011_sec_7"
    },
    {
      "action": "Verify that the transfer is necessary for the performance of a lawful contract with the provider of information or that the provider has consented to the data transfer.",
      "provision_id": "spdi_rules_2011_sec_7"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify if the event qualifies as a cyber security incident as defined in the annexure.",
      "provision_id": "cert_in_directions_2022_annex_1"
    },
    {
      "action": "Report the cyber incident to CERT-In via email, phone, or fax within 6 hours of noticing or being brought to notice of the incident.",
      "provision_id": "cert_in_directions_2022_dir_2"
    }
  ]
}

{
  "steps": [
    {
      "action": "Enable and maintain ICT system logs securely within Indian jurisdiction for a rolling period of 180 days.",
      "provision_id": "cert_in_directions_2022_dir_4"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify sensitive personal data or information as data relating to passwords, financial information (bank/card details), physical/physiological/mental health conditions, sexual orientation, medical records/history, and biometric information.",
      "provision_id": "spdi_rules_2011_sec_3"
    },
    {
      "action": "Include any details relating to the aforementioned categories provided to a body corporate for service, or information received/stored/processed under a lawful contract.",
      "provision_id": "spdi_rules_2011_sec_3"
    },
    {
      "action": "Exclude any information that is freely available or accessible in the public domain, or information furnished under the Right to Information Act, 2005, or any other law in force.",
      "provision_id": "spdi_rules_2011_sec_3"
    },
    {
      "action": "Classify biometric information collected and stored in electronic form as sensitive personal data or information, subject to the Information Technology Act, 2000 and its rules.",
      "provision_id": "aadhaar_act_2016_sec_30"
    }
  ]
}

{
  "steps": [
    {
      "action": "Implement and maintain reasonable security practices and procedures to protect sensitive personal data or information from unauthorized access, damage, use, modification, disclosure, or impairment.",
      "provision_id": "information_technology_act_2000_sec_43A"
    },
    {
      "action": "Ensure compliance with security standards to avoid liability for damages by way of compensation to any person affected by wrongful loss or gain resulting from negligence in data protection.",
      "provision_id": "information_technology_act_2000_sec_43A"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the limited liability partnership has at least two partners.",
      "provision_id": "llp_act_2008_sec_6"
    },
    {
      "action": "Appoint at least two designated partners who are individuals, ensuring at least one of them is a resident in India.",
      "provision_id": "llp_act_2008_sec_7"
    },
    {
      "action": "Ensure each designated partner obtains a Designated Partner Identification Number (DPIN) from the Central Government.",
      "provision_id": "llp_act_2008_sec_7"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure there is no security interest in the company's assets subsisting or in force at the time of application.",
      "provision_id": "llp_act_2008_schedule_3"
    },
    {
      "action": "Ensure that the partners of the resulting limited liability partnership comprise all the shareholders of the company and no one else.",
      "provision_id": "llp_act_2008_schedule_3"
    },
    {
      "action": "Comply with the requirements for conversion as set out in the Third Schedule and the provisions of the Chapter.",
      "provision_id": "llp_act_2008_sec_56"
    },
    {
      "action": "Submit the required documents to the Registrar for registration.",
      "provision_id": "llp_act_2008_sec_58"
    },
    {
      "action": "Inform the concerned Registrar of Companies about the conversion within fifteen days of the date of registration.",
      "provision_id": "llp_act_2008_sec_58"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure that any compensation agreement involving a lump sum payment is submitted to the Commissioner for registration, noting that once registered, such an agreement is enforceable under the Act notwithstanding the provisions of the Indian Contract Act, 1872.",
      "provision_id": "eca_1923_sec_28"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify the breach of contract where a specific sum or penalty is stipulated in the contract.",
      "provision_id": "contract_act_1872_sec_74"
    },
    {
      "action": "Claim reasonable compensation from the party in breach, regardless of whether actual loss or damage is proven, provided it does not exceed the stipulated amount.",
      "provision_id": "contract_act_1872_sec_74"
    }
  ]
}

{
  "steps": [
    {
      "action": "Define a contract of indemnity as an agreement where one party promises to save the other from loss caused by the conduct of the promisor or any other person.",
      "provision_id": "contract_act_1872_sec_124"
    },
    {
      "action": "Recover all damages the indemnity-holder is compelled to pay in a suit related to the matter covered by the indemnity.",
      "provision_id": "contract_act_1872_sec_125"
    },
    {
      "action": "Recover all costs the indemnity-holder is compelled to pay in such a suit.",
      "provision_id": "contract_act_1872_sec_125"
    },
    {
      "action": "Recover all sums paid by the indemnity-holder under the terms of any compromise of such a suit, provided the indemnity-holder acted within the scope of their authority.",
      "provision_id": "contract_act_1872_sec_125"
    }
  ]
}

{
  "steps": [
    {
      "action": "Determine if the company meets the threshold of having a net worth of rupees five hundred crore or more, a turnover of rupees one thousand crore or more, or a net profit of rupees five crore or more during the immediately preceding financial year.",
      "provision_id": "ca_2013_sec_135"
    },
    {
      "action": "If the threshold is met, constitute a Corporate Social Responsibility Committee of the Board.",
      "provision_id": "ca_2013_sec_135"
    },
    {
      "action": "Ensure the company spends at least two per cent of the average net profits made during the three immediately preceding financial years in every financial year.",
      "provision_id": "ca_2013_sec_135"
    },
    {
      "action": "If any amount remains unspent for an ongoing project, transfer it to a special account within thirty days from the end of the financial year, or transfer it to a Fund specified in Schedule VII if the special account requirement is not met.",
      "provision_id": "ca_2013_sec_135"
    }
  ]
}

{
  "steps": [
    {
      "action": "Appoint an individual or a firm as an auditor at the first annual general meeting to hold office until the conclusion of the sixth annual general meeting.",
      "provision_id": "ca_2013_sec_139"
    },
    {
      "action": "Ensure the auditor is appointed for no more than one term of five consecutive years for an individual, or two terms of five consecutive years for an audit firm, if the company is a listed company or falls under prescribed classes.",
      "provision_id": "ca_2013_sec_139"
    },
    {
      "action": "Fix the remuneration of the auditor in the general meeting or in such manner as determined therein.",
      "provision_id": "ca_2013_sec_142"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the company is authorized to issue securities by way of a rights issue as per the provisions of the Act.",
      "provision_id": "ca_2013_sec_23"
    },
    {
      "action": "Offer the shares to existing equity shareholders in proportion to their existing shareholding.",
      "provision_id": "ca_2013_sec_62"
    },
    {
      "action": "Issue a notice specifying the number of shares offered and a time period for acceptance of not less than fifteen days and not exceeding thirty days.",
      "provision_id": "ca_2013_sec_62"
    },
    {
      "action": "Recognize the right of the shareholders to renounce the shares offered to them, unless the articles of the company provide otherwise.",
      "provision_id": "ca_2013_sec_62"
    },
    {
      "action": "Hold the offer in abeyance if an instrument of transfer for the shares has been delivered to the company but not yet registered.",
      "provision_id": "ca_2013_sec_126"
    }
  ]
}

{
  "steps": [
    {
      "action": "Verify that the person is not an undischarged insolvent.",
      "provision_id": "[ibc_2016_sec_29A]"
    },
    {
      "action": "Confirm the person is not a wilful defaulter.",
      "provision_id": "[ibc_2016_sec_29A]"
    },
    {
      "action": "Ensure the person has not been convicted for any offence punishable with imprisonment for 2 years or more.",
      "provision_id": "[ibc_2016_sec_29A]"
    },
    {
      "action": "Confirm the person is not disqualified to act as a director under the Companies Act.",
      "provision_id": "[ibc_2016_sec_29A]"
    },
    {
      "action": "Verify the person does not have prohibited active accounts classified as non-performing assets.",
      "provision_id": "[ibc_2016_sec_29A]"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure all e-commerce operations comply with measures prescribed by the Central Government to prevent unfair trade practices.",
      "provision_id": "[consumer_protection_act_2019_sec_93]"
    },
    {
      "action": "Acknowledge that the Central Consumer Protection Authority is established to regulate and investigate matters relating to unfair trade practices.",
      "provision_id": "[consumer_protection_act_2019_sec_10]"
    },
    {
      "action": "Be aware that complaints regarding unfair trade practices can be forwarded to the District Collector, Commissioner, or Central Authority.",
      "provision_id": "[consumer_protection_act_2019_sec_17]"
    },
    {
      "action": "Note that the District Collector has the power to inquire into or investigate matters relating to unfair trade practices upon receiving a complaint or reference.",
      "provision_id": "[consumer_protection_act_2019_sec_16]"
    }
  ]
}

{
  "steps": [
    {
      "action": "Verify that the subject matter is not frivolous or contrary to well-established natural laws.",
      "provision_id": "patents_act_1970_sec_3"
    },
    {
      "action": "Ensure the invention is not contrary to public order, morality, or harmful to human, animal, plant life, or the environment.",
      "provision_id": "patents_act_1970_sec_3"
    },
    {
      "action": "Confirm the subject is not a mere discovery of a scientific principle, abstract theory, or a living/non-living thing occurring in nature.",
      "provision_id": "patents_act_1970_sec_3"
    },
    {
      "action": "Ensure the invention is not a mere discovery of a new form, property, or use of a known substance that fails to enhance efficacy, or a mere use of a known process/machine unless it results in a new product or employs a new reactant.",
      "provision_id": "patents_act_1970_sec_3"
    },
    {
      "action": "Exclude methods of agriculture or horticulture from patentable inventions.",
      "provision_id": "patents_act_1970_sec_3"
    },
    {
      "action": "Exclude processes for medicinal, surgical, curative, prophylactic, diagnostic, or therapeutic treatment of humans or animals.",
      "provision_id": "patents_act_1970_sec_3"
    }
  ]
}

{
  "steps": [
    {
      "action": "The term of every patent granted is twenty years from the date of filing of the application or the international filing date for PCT applications.",
      "provision_id": "[patents_act_1970_sec_53]"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify the eligible applicant, which includes the true and first inventor, or the assignee of the person claiming to be the true and first inventor.",
      "provision_id": "[patents_act_1970_sec_6]"
    },
    {
      "action": "If the application is made by an assignee, furnish proof of the right to make the application with or shortly after the application.",
      "provision_id": "[patents_act_1970_sec_7]"
    },
    {
      "action": "State in the application that the applicant possesses the invention and name the true and first inventor; if the applicant is not the inventor, provide a declaration that the applicant believes the named person to be the true and first inventor.",
      "provision_id": "[patents_act_1970_sec_7]"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the patent assignment is in writing, reduced to a document embodying all agreed terms and conditions, and duly executed by the parties.",
      "provision_id": "patents_act_1970_sec_68"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the trademark is distinctive and not merely descriptive of the goods or services, nor customary in trade practices, to avoid absolute grounds for refusal.",
      "provision_id": "[trademarks_act_1999_sec_9]"
    },
    {
      "action": "Verify the mark does not deceive the public, hurt religious susceptibilities, contain obscene matter, or violate the Emblems and Names (Prevention of Improper Use) Act, 1950.",
      "provision_id": "[trademarks_act_1999_sec_9]"
    },
    {
      "action": "Ensure the mark does not consist exclusively of shapes resulting from the nature of the goods, shapes necessary for technical results, or shapes providing substantial value.",
      "provision_id": "[trademarks_act_1999_sec_9]"
    },
    {
      "action": "Check for identity or similarity to earlier trademarks to avoid refusal based on the likelihood of confusion or association by the public.",
      "provision_id": "[trademarks_act_1999_sec_11]"
    },
    {
      "action": "Ensure the mark does not take unfair advantage of or detrimentally affect the reputation of an earlier well-known trademark.",
      "provision_id": "[trademarks_act_1999_sec_11]"
    },
    {
      "action": "Confirm the mark does not infringe upon existing unregistered trademarks protected by the law of passing off or existing copyright laws.",
      "provision_id": "[trademarks_act_1999_sec_11]"
    },
    {
      "action": "Acknowledge that the Registrar may refuse an application if it does not meet the requirements for registration or impose conditions/limitations.",
      "provision_id": "[trademarks_act_1999_sec_18]"
    }
  ]
}

{
  "steps": [
    {
      "action": "Note that the initial registration of a trade mark is valid for a period of ten years.",
      "provision_id": "trademarks_act_1999_sec_25"
    },
    {
      "action": "Apply to the Registrar for renewal within the prescribed period and pay the prescribed fee to renew the registration for a further ten years.",
      "provision_id": "trademarks_act_1999_sec_25"
    },
    {
      "action": "If the renewal conditions are not met, file a late renewal application with a surcharge within six months of the expiry date.",
      "provision_id": "trademarks_act_1999_sec_25"
    },
    {
      "action": "If the mark is removed for non-payment, apply for restoration within one year of expiry, provided the Registrar is satisfied it is just to do so.",
      "provision_id": "trademarks_act_1999_sec_25"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify if a person, who is not the registered proprietor or a permitted user, uses a mark identical or deceptively similar to a registered trademark in the course of trade, in a manner likely to be taken as a trademark, or in a way that causes confusion or association with the public.",
      "provision_id": "trademarks_act_1999_sec_29"
    },
    {
      "action": "Recognize that infringement also occurs if a mark is used on dissimilar goods or services where the registered mark has a reputation in India and the use takes unfair advantage of or is detrimental to its distinctive character (dilution), or if the mark is used as a trade name or in advertising that takes unfair advantage.",
      "provision_id": "trademarks_act_1999_sec_29"
    },
    {
      "action": "Note that for certification trade marks, infringement occurs when a person who is not the registered proprietor or an authorized user uses an identical or deceptively similar mark in the course of trade.",
      "provision_id": "trademarks_act_1999_sec_75"
    },
    {
      "action": "Ensure the claim is not excluded by limits on the effect of a registered trademark, such as honest industrial practices, descriptive use, or the exhaustion of rights after goods are lawfully acquired.",
      "provision_id": "trademarks_act_1999_sec_30"
    },
    {
      "action": "Institute a suit for infringement before a District Court having jurisdiction, which includes the location where the plaintiff resides, carries on business, or works for gain.",
      "provision_id": "trademarks_act_1999_sec_134"
    },
    {
      "action": "Seek relief from the court, which may include an injunction, and at the plaintiff's option, either damages or an account of profits, with or without an order for the destruction of infringing materials.",
      "provision_id": "trademarks_act_1999_sec_135"
    },
    {
      "action": "Be aware that the court may grant ex parte or interlocutory orders for the discovery of documents or the preservation of infringing goods and evidence.",
      "provision_id": "trademarks_act_1999_sec_135"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the franchisee is not a national of a country that does not accord Indian citizens reciprocal trademark rights.",
      "provision_id": "trademarks_act_1999_sec_155"
    },
    {
      "action": "Draft a written licensing agreement specifying the permitted use, quality control measures, goods/services covered, and any time limitations or conditions.",
      "provision_id": "trademarks_act_1999_sec_49"
    },
    {
      "action": "Prepare an affidavit detailing the relationship between the proprietor and the franchisee, including the degree of quality control exercised by the proprietor.",
      "provision_id": "trademarks_act_1999_sec_49"
    },
    {
      "action": "Jointly apply in writing to the Registrar, submitting the application along with the written licensing agreement (or authenticated copy) and the required affidavit.",
      "provision_id": "trademarks_act_1999_sec_49"
    },
    {
      "action": "Request the Registrar to keep the filed information confidential from trade rivals if necessary.",
      "provision_id": "trademarks_act_1999_sec_49"
    },
    {
      "action": "Upon satisfaction of requirements, the Registrar will register the franchisee as a registered user.",
      "provision_id": "trademarks_act_1999_sec_49"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure you have the licence or written consent of the registered proprietor before applying, importing, or publishing a registered design or an imitation of it for the purpose of sale.",
      "provision_id": "[designs_act_2000_sec_22]"
    },
    {
      "action": "Avoid unauthorized use, as contravention may lead to liability for damages, injunctions, or payments to the registered proprietor.",
      "provision_id": "[designs_act_2000_sec_22]"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the agreement is made by parties competent to contract, with free consent, lawful consideration, and a lawful object to establish a valid contract.",
      "provision_id": "contract_act_1872_sec_10"
    },
    {
      "action": "Verify that the electronic communication of proposals and acceptances is used, as contracts formed through electronic means are not unenforceable solely due to the electronic format.",
      "provision_id": "it_act_2000_sec_10A"
    },
    {
      "action": "Ensure that the consent for the contract is not obtained through coercion, fraud, or misrepresentation, as such agreements are voidable.",
      "provision_id": "contract_act_1872_sec_19"
    },
    {
      "action": "If the contract is made on behalf of a company, ensure it is signed by a key managerial personnel or an officer or employee duly authorised by the Board.",
      "provision_id": "ca_2013_sec_21"
    }
  ]
}

{
  "steps": [
    {
      "action": "The provided provisions do not contain information regarding the turnover threshold for compulsory GST registration.",
      "provision_id": "N/A"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the registered person uses the goods or services in the course or furtherance of business.",
      "provision_id": "cgst_act_2017_sec_16"
    },
    {
      "action": "Possess a valid tax invoice, debit note, or other prescribed tax-paying document issued by a registered supplier.",
      "provision_id": "cgst_act_2017_sec_16"
    },
    {
      "action": "Ensure the goods or services have been received.",
      "provision_id": "cgst_act_2017_sec_16"
    },
    {
      "action": "Ensure the document contains all applicable particulars as specified in Chapter VI.",
      "provision_id": "cgst_rules_2017_rule_36"
    },
    {
      "action": "Furnish the relevant information from the document in FORM GSTR-2.",
      "provision_id": "cgst_rules_2017_rule_36"
    },
    {
      "action": "Self-assess the eligible input tax credit in the return to have it credited provisionally to the electronic credit ledger.",
      "provision_id": "cgst_act_2017_sec_41"
    }
  ]
}

{
  "steps": [
    {
      "action": "Verify that the aggregate turnover in the preceding financial year did not exceed fifty lakh rupees.",
      "provision_id": "cgst_act_2017_sec_10"
    },
    {
      "action": "If applying for new registration, provide the option to pay tax under section 10 in Part B of FORM GST REG-01.",
      "provision_id": "cgst_rules_2017_rule_3"
    },
    {
      "action": "If already registered, electronically file an intimation in FORM GST CMP-02 on the common portal prior to the commencement of the financial year.",
      "provision_id": "cgst_rules_2017_rule_3"
    },
    {
      "action": "Ensure compliance with the conditions mentioned in section 10 and the relevant rules to maintain the validity of the composition levy.",
      "provision_id": "cgst_rules_2017_rule_6"
    }
  ]
}

{
  "steps": [
    {
      "action": "Include the name, address, and Goods and Services Tax Identification Number of the supplier.",
      "provision_id": "cgst_rules_2017_rule_46"
    },
    {
      "action": "Include a consecutive serial number not exceeding sixteen characters, unique for a financial year, containing alphabets, numerals, or special characters (hyphen or dash and slash).",
      "provision_id": "cgst_rules_2017_rule_46"
    },
    {
      "action": "Include the date of issue of the invoice.",
      "provision_id": "cgst_rules_2017_rule_46"
    },
    {
      "action": "Include the name, address, and Goods and Services Tax Identification Number or Unique Identity Number of the recipient, if registered.",
      "provision_id": "cgst_rules_2017_rule_46"
    },
    {
      "action": "Include the name and address of the recipient and the address of delivery, along with the name of the State and its code, if the recipient is unregistered.",
      "provision_id": "cgst_rules_2017_rule_46"
    },
    {
      "action": "Include the Harmonised System of Nomenclature code for goods or services.",
      "provision_id": "cgst_rules_2017_rule_46"
    },
    {
      "action": "Include a description of the goods or services.",
      "provision_id": "cgst_rules_2017_rule_46"
    },
    {
      "action": "Include the quantity in case of goods and the unit or Unique Quantity Code thereof.",
      "provision_id": "cgst_rules_2017_rule_46"
    },
    {
      "action": "Include the total value of the supply of goods or services or both.",
      "provision_id": "cgst_rules_2017_rule_46"
    },
    {
      "action": "Include the taxable value of the supply taking into account any discount or abatement.",
      "provision_id": "cgst_rules_2017_rule_46"
